export default function Hero() {
  return (
    <section className="hero" id="home">
      <div className="container hero-content">
        <h2>Premium Aquaculture Seeds & Seafood Exports</h2>
        <p>Connecting Coastal Andhra Pradesh's finest hatcheries with aquaculture farmers and global seafood markets</p>
        <div className="hero-btns">
          <a href="#contact" className="btn btn-primary">Get Expert Consultation</a>
          <a href="#products" className="btn btn-secondary">Explore Our Products</a>
        </div>
      </div>
    </section>
  );
}
